electrolytes = [
 {"cat":"Acid-Base","q":"Give the primary event and direction of change in the 4 acid-base disturbances.",
  "a": "<ul><li><b>Metabolic acidosis:</b> primary ↓HCO₃⁻ → pH↓, compensatory CO₂↓ (hyperventilation)</li><li><b>Metabolic alkalosis:</b> primary ↑HCO₃⁻ → pH↑, CO₂↑</li><li><b>Respiratory acidosis:</b> primary CO₂ retention → pH↓, kidneys retain HCO₃⁻ (HCO₃↑)</li><li><b>Respiratory alkalosis:</b> primary CO₂ loss → pH↑, kidneys excrete HCO₃⁻ (HCO₃↓)</li></ul>"},
 {"cat":"Acid-Base","q":"Write the anion gap formula and what it represents.",
  "a": "AG = Na⁺ − (HCO₃⁻ + Cl⁻). Plasma is electro-neutral; unmeasured anions (sulfate, phosphate, organic anions) slightly exceed unmeasured cations — that difference is the anion gap. ↑AG occurs with ↓ unmeasured cations (e.g., hypokalemia) or ↑ unmeasured anions (e.g., hyperphosphatemia)."},
 {"cat":"Acid-Base","q":"List causes of high-anion-gap metabolic acidosis.",
  "a": "Ketoacidosis; renal failure (uremia); lactic acidosis; massive rhabdomyolysis; exogenous toxins (salicylate, methanol, ethylene glycol, metformin). Mnemonic <b>K.U.S.M.A.U.L.</b> — Ketoacidosis, Uremia, Salicylates, Methanol, Alcohol, Uric acid (rhabdomyolysis), Lactic acidosis."},
 {"cat":"Acid-Base","q":"List causes of normal-anion-gap (hyperchloremic) metabolic acidosis.",
  "a": "GI loss of HCO₃⁻ (diarrhea, enteric fistula); renal HCO₃⁻ loss (<b>proximal type II RTA</b>); failure of H⁺ secretion (<b>distal type I RTA</b>); acid infusion (ammonium chloride, hyperalimentation)."},
 {"cat":"Acid-Base","q":"What is the hallmark respiratory sign of metabolic acidosis?",
  "a": "<b>Kussmaul respiration</b> — rapid, deep sighing breathing as the body blows off CO₂ to compensate."},
 {"cat":"Acid-Base","q":"When is alkali therapy indicated in metabolic acidosis and what is the deficit formula?",
  "a": "To raise pH above <b>7.20</b> when HCO₃⁻ low + PCO₂ near the compensation limit (~15 mmHg), or when well-compensated acidosis threatens respiratory failure. IV NaHCO₃ deficit = (Desired HCO₃⁻ − Measured HCO₃⁻) × 0.5 × body weight (kg). Oral HCO₃⁻ for chronic acidosis (e.g., RTA)."},
 {"cat":"Acid-Base","q":"How is metabolic alkalosis classified (first step)?",
  "a": "By <b>urine chloride</b>: <b>Chloride-responsive</b> (&lt;20 mEq/L), <b>Chloride-resistant</b> (&gt;20 mEq/L), and other causes (alkali loading)."},
 {"cat":"Acid-Base","q":"List causes of chloride-responsive metabolic alkalosis.",
  "a": "Loss of gastric secretions (vomiting, NG suction); loss of colonic secretions (chloridorrhea, villous adenoma); volume depletion; thiazide/loop diuretics (after discontinuation); cystic fibrosis."},
 {"cat":"Acid-Base","q":"List causes of chloride-resistant metabolic alkalosis — with and without hypertension.",
  "a": "<b>With hypertension:</b> hyperaldosteronism (Conn, GRA), Cushing syndrome, exogenous steroids, Liddle syndrome, renovascular hypertension. <b>Without hypertension:</b> Bartter syndrome, Gitelman syndrome, severe K⁺ depletion, current thiazide/loop diuretic use, hypomagnesemia."},
 {"cat":"Acid-Base","q":"What signs point to hypocalcemia in metabolic alkalosis?",
  "a": "Tetany, <b>Chvostek sign, Trousseau sign</b>, perioral tingling, muscle cramps, carpopedal spasms (decreased ionized calcium)."},
 {"cat":"Acid-Base","q":"How is chloride-responsive metabolic alkalosis treated?",
  "a": "Volume-depleted: <b>isotonic 0.9% NaCl</b> + potassium chloride. Volume-overloaded (edematous): potassium chloride ± carbonic anhydrase inhibitors or K⁺-sparing diuretics. Chloride-resistant: treat the specific cause (hyperaldosteronism, stop diuretics, replace Mg²⁺/K⁺)."},
 {"cat":"Hyponatremia","q":"Define hyponatremia and pseudohyponatremia.",
  "a": "Hyponatremia: serum Na <b>&lt;135 mmol/L</b>. Most common form is <b>dilutional</b> (water retention). <b>Pseudohyponatremia:</b> spuriously low measured Na with normal true plasma Na — when serum lipids/proteins are markedly elevated; plasma osmolality stays normal (vs low in true hypotonic hyponatremia)."},
 {"cat":"Hyponatremia","q":"What are the pathological effects and neurological manifestations of hyponatremia?",
  "a": "Water shifts ECF → ICF → <b>cell swelling → brain edema</b>. Manifestations: altered personality, lethargy, confusion → stupor, neuromuscular hyperexcitability, hyperreflexia, <b>seizures, coma, death</b>. Severity correlates with severity and <b>rate of development</b>."},
 {"cat":"Hyponatremia","q":"Classify hyponatremia by osmolality and volume status.",
  "a": "By osmolality: <b>Hypertonic &amp; isotonic = pseudohyponatremia</b>; <b>hypotonic = true hyponatremia</b>, then subclassified by volume: <b>hypervolemic</b> (HF, cirrhosis, nephrotic, CKD), <b>euvolemic</b> (SIADH — prototype, primary polydipsia, hypothyroidism, thiazides), <b>hypovolemic</b> (extra-renal loss — vomiting/diarrhea; renal loss — diuretics, adrenal insufficiency, salt-losing nephritis, recovery phase of AKI)."},
 {"cat":"Hyponatremia","q":"What is the risk of over-rapid correction of chronic hyponatremia?",
  "a": "<b>Osmotic demyelination syndrome (central pontine myelinolysis)</b> — correct slowly in chronic cases. Fluid of choice by volume status: isotonic 0.9% NaCl (hypo/euvolemic), hypertonic 3% NaCl + loop diuretics (hyper/euvolemic); vasopressin antagonists (conivaptan, tolvaptan) for SIADH."},
 {"cat":"Hypernatremia","q":"Define hypernatremia and explain why it almost always means water deficit.",
  "a": "Serum Na <b>&gt;145 mmol/L</b>. Sodium is an osmotically effective ECF solute, so hypernatremia always reflects <b>hypertonicity</b> from a water deficit (TBW deficit &gt; Na deficit). Normally ADH and thirst defend against it — it occurs when these defenses fail."},
 {"cat":"Hypernatremia","q":"What are the pathological effects of hypernatremia on the brain?",
  "a": "Water shifts ICF → ECF → <b>cell shrinkage</b> → neurological sequelae and <b>intracerebral hemorrhage</b> (punctate or major vessel disruption)."},
 {"cat":"Hypernatremia","q":"Classify hypernatremia by volume status with examples.",
  "a": "<ul><li><b>Hypervolemic:</b> excessive sodium administration (hypertonic 3% saline, NaHCO₃)</li><li><b>Euvolemic:</b> pure water loss — renal (diabetes insipidus, low urine osmolality) vs extra-renal (rhabdomyolysis, high urine osmolality)</li><li><b>Hypovolemic:</b> hypotonic fluid loss — renal Na loss (diuretics, polyuric ATN) vs extra-renal (GIT/respiratory/skin)</li></ul>"},
 {"cat":"Hypernatremia","q":"How is hypernatremia treated?",
  "a": "First resuscitation of volume with <b>isotonic 0.9% NaCl</b>; then gradual maintenance correction: TBW deficit = 0.6 × premorbid weight × (1 − 140/Na) + daily requirements, using oral water, IV 5% glucose or 0.45% NaCl. <b>Correct gradually — 0.5–1 mmol/L/hour — to avoid brain edema</b>."},
 {"cat":"Hyperkalemia","q":"Define hyperkalemia and list causes of increased K⁺ release from cells.",
  "a": "Serum K <b>&gt;5.5 mmol/L</b>. Increased release: <b>pseudo-hyperkalemia</b> (in-vitro hemolysis, polycythemia/leukocytosis), metabolic acidosis, insulin deficiency/hyperglycemia/hyperosmolality, increased catabolism (trauma, tumor lysis), β-blockade, exercise, digitalis overdose."},
 {"cat":"Hyperkalemia","q":"List causes of reduced urinary K⁺ excretion.",
  "a": "Renal failure; hypoaldosteronism (primary/secondary); volume depletion; <b>type IV RTA</b>; drugs impairing aldosterone secretion (<b>ACEIs, ARBs, NSAIDs, cyclosporin</b>); drugs causing aldosterone resistance (<b>spironolactone, trimethoprim, heparin</b>)."},
 {"cat":"Hyperkalemia","q":"What are the manifestations of hyperkalemia and the membrane mechanism?",
  "a": "High extracellular K⁺ <b>depolarizes the resting membrane potential</b> → nerve/muscle/cardiac cells become <b>less excitable</b> → muscle weakness/paralysis, paresthesias, impaired cardiac conduction, irregular pulse, cardiac standstill."},
 {"cat":"Hyperkalemia","q":"Describe the stepwise treatment of hyperkalemia.",
  "a": "Urgent if weakness/paralysis, ECG changes, arrhythmia, or K ≥7. <ul><li><b>1. Stabilize membrane:</b> IV calcium gluconate (10 ml over 10 min)</li><li><b>2. Shift K⁺ into cells:</b> β₂-agonists (salbutamol inhaled; avoid in IHD), insulin + dextrose, NaHCO₃ (rapid, brief)</li><li><b>3. Remove K⁺:</b> loop diuretics, K⁺ exchange resins (sodium polystyrene sulfonate — intestinal necrosis risk), <b>hemodialysis</b> (refractory/emergency, K &gt;7 or ECG changes)</li><li><b>4. Monitor:</b> continuous ECG + serial K at 1–2 h</li></ul>"},
 {"cat":"Hyperkalemia","q":"Give the ECG sequence of hyperkalemia.",
  "a": "Early: <b>tall peaked T waves</b> → intermediate: <b>PR prolongation, ST depression, loss of P waves</b> → late/severe: <b>widened QRS, VT, cardiac standstill</b> (sine wave). ECG changes = emergency trigger — treat immediately."},
 {"cat":"Hypokalemia","q":"Define hypokalemia and list its causes.",
  "a": "Serum K <b>&lt;3.5 mmol/L</b>. Causes: spurious (sample left at room temp, leukocytosis, recent insulin); ↓ intake; shift into cells (alkalosis, insulin, β-agonists, stress); <b>renal loss</b> (diuretics → RAAS activation, hyperaldosteronism/steroids, proximal RTA, hypomagnesemia, polyuria); extra-renal loss (vomiting/gastric aspiration → alkalosis + volume depletion → aldosterone)."},
 {"cat":"Hypokalemia","q":"Compare Bartter and Gitelman syndromes.",
  "a": "<b>Bartter:</b> impaired Na-Cl reabsorption in the <b>loop of Henle</b> — findings mimic a loop diuretic, <b>increased urinary calcium</b>, diagnosed in childhood, may have growth/mental retardation. <b>Gitelman:</b> defect in the <b>distal Na-Cl transporter</b> — findings mimic a thiazide diuretic."},
 {"cat":"Hypokalemia","q":"What causes hypokalemic periodic paralysis?",
  "a": "A defect in a <b>voltage-gated calcium channel</b>; triggered by strenuous exercise followed by rest, high-carbohydrate or high-sodium meals, and sudden temperature changes."},
 {"cat":"Hypokalemia","q":"Describe the ECG of hypokalemia.",
  "a": "<b>ST-segment and T-wave depression with prominent U waves</b>."},
 {"cat":"Hypokalemia","q":"How is hypokalemia treated?",
  "a": "Treat the cause. IV KCl when serum K <b>&lt;2.5 mmol/L</b>; max rate <b>&lt;20 mmol/hour</b>. Oral K preferred otherwise. <b>Check serum Mg</b> — potassium cannot be restored if magnesium is low. ECG monitoring required."},
]

