# GROUP 05 — Structural & Vascular Renal Diseases
# ============================================================
structural = [
 {"cat":"Cysts","q":"What is the incidence and nature of simple (solitary) renal cysts?",
  "a": "Common — in <b>50% of persons &gt;50 years</b>; not inherited; do not affect renal function; usually &lt;2 cm, solitary, cortical, often bulging through the renal capsule; may be multiple &amp; bilateral."},
 {"cat":"Cysts","q":"When are simple renal cysts symptomatic, and what complications can occur?",
  "a": "Rarely: abdominal mass; <b>hematuria (rare — raises suspicion of renal cell carcinoma)</b>; hypertension from compression of intra-renal vessels. Complications: hemorrhage, infection (fever, pain, pyuria), carcinoma. Renal function stays normal; prognosis excellent."},
 {"cat":"Cysts","q":"What are the ultrasound criteria of a simple renal cyst?",
  "a": "<ul><li>Echoes-free (homogeneous)</li><li>Sharply demarcated with a smooth thin wall</li><li><b>Enhanced back wall</b></li></ul>On CT: no enhancement with contrast — <b>a simple cyst does not enhance; renal cell carcinoma does</b>."},
 {"cat":"Cysts","q":"How are simple renal cysts differentiated from renal abscess and PCKD?",
  "a": "<b>Abscess:</b> fever, pain, pyuria; thick irregular wall with internal echoes/debris. <b>PCKD:</b> multiple bilateral cysts, family history, systemic involvement, renal failure, hypertension, extra-renal cysts."},
 {"cat":"Cysts","q":"How is a simple renal cyst managed?",
  "a": "Asymptomatic → periodic re-evaluation. Large cyst → aspiration + alcohol instillation; if &gt;500 ml of fluid → surgical drainage. Infected cyst → antibiotics (exclude abscess). Hypertension may improve after decompression."},
 {"cat":"ADPKD","q":"Give the genetics of ADPKD.",
  "a": "Autosomal dominant; defect on <b>chromosome 16 → ADPKD-1</b>, <b>chromosome 4 → ADPKD-2</b>. Common age of presentation: middle age (~40 y). It is a <b>systemic disease</b>."},
 {"cat":"ADPKD","q":"List the renal clinical features of ADPKD with their mechanisms.",
  "a": "Hematuria (cyst rupture into pelvis, stone, UTI); renal infection (flank pain, fever — urine may be normal because the cyst doesn't communicate with the urinary tract — <b>use blood cultures</b>); nephrolithiasis (mainly calcium oxalate); abdominal/flank pain (infection, bleeding, rupture, stones); <b>hypertension in ~50%</b> (cyst-induced ischemia → RAAS activation); mild anemia relative to renal failure; palpable irregular kidneys."},
 {"cat":"ADPKD","q":"List the extra-renal associations of ADPKD.",
  "a": "Hepatic cysts (50%, usually no functional impairment); pancreatic and splenic cysts; colonic diverticulosis; <b>cerebral berry aneurysms → subarachnoid hemorrhage</b>; mitral valve prolapse, aortic valve abnormalities, aortic aneurysms."},
 {"cat":"ADPKD","q":"How is ADPKD diagnosed?",
  "a": "Clinical: middle age, family history (<b>75%</b>), hematuria/mild proteinuria, slow steady decline in renal function. Imaging: US — <b>≥5 cysts scattered in cortex and medulla of each kidney</b>; CT if US unclear; IVP shows stretching/distortion of calyces."},
 {"cat":"ADPKD","q":"How is renal infection in ADPKD treated?",
  "a": "Parenteral antibiotics with cyst penetration (<b>ciprofloxacin, trimethoprim-sulfamethoxazole</b>) for 2 weeks followed by long-term oral therapy (months)."},
 {"cat":"ADPKD","q":"What are the key treatment cautions in ADPKD?",
  "a": "ACEIs/ARBs used with caution in renal impairment (especially with large cysts); diuretics cautiously (hypokalemia may promote cyst development); hematuria usually resolves in 7 days with bed rest + hydration — <b>recurrent bleeding suggests renal cell carcinoma</b>; renal failure: treat as usual but <b>avoid peritoneal dialysis</b>."},
 {"cat":"ARPKD","q":"Give the genetics and presentation of ARPKD.",
  "a": "Autosomal recessive, defect on <b>chromosome 6</b>; parents unaffected. Presents perinatally (<b>pulmonary hypoplasia → high mortality</b>), in early life (liver-dominant: hepatic fibrosis, portal hypertension, GI bleeding, hepatosplenomegaly), or later (renal-dominant: abdominal mass, HTN, recurrent UTIs, renal failure in adolescence). May associate with berry/aortic aneurysms and Ehlers-Danlos."},
 {"cat":"ARPKD","q":"How is ARPKD diagnosed?",
  "a": "US is the test of choice: <b>enlarged kidneys, smooth, increased echogenicity</b> (normal US does not exclude). Confirmed by absent family history (normal US in parents), liver cysts, and other ARPKD manifestations."},
 {"cat":"HTN-Nephrosclerosis","q":"Define hypertensive nephrosclerosis.",
  "a": "Chronic kidney disease that <b>complicates arterial hypertension</b> — a diagnosis based on <b>clinical criteria, not renal biopsy</b>."},
 {"cat":"HTN-Nephrosclerosis","q":"List the 5 clinical criteria for diagnosing hypertensive nephrosclerosis.",
  "a": "<ol><li>History of <b>prolonged hypertension (&gt;10 years)</b></li><li><b>Low-grade proteinuria (&lt;2 gm/day)</b></li><li>Grade I or II hypertensive retinopathy</li><li><b>Small scarred kidneys</b></li><li>No evidence of primary renal disease</li></ol>"},
 {"cat":"HTN-Nephrosclerosis","q":"What is the BP goal in CKD and which diuretic principle applies?",
  "a": "Intensive BP goal <b>&lt;130/80 mmHg</b>; low-salt diet is critical. <b>Diuretics are the cornerstone</b> — as GFR falls, higher diuretic doses are needed to achieve a natriuretic response."},
 {"cat":"HTN-Nephrosclerosis","q":"Which antihypertensives are used in proteinuric CKD, and which cautions apply?",
  "a": "<b>ACEIs/ARBs</b> first-line. <b>Non-dihydropyridine CCBs</b> (verapamil/diltiazem) reduce albuminuria and slow decline. <b>Dihydropyridine CCBs must NOT be monotherapy</b> in proteinuric CKD — always combine with a RAAS blocker. <b>Mineralocorticoid antagonists (spironolactone)</b> are fourth-line for resistant HTN but limited in advanced CKD by <b>hyperkalemia and AKI</b> risk."},
]

